const multer = require('multer');
const multerS3 = require('multer-s3');
const upload = multer({
  storage: multerS3({
    s3: s3Client,
    bucket: process.env.EXPENSE_RECEIPTS_BUCKET,
    key: (req, file, cb) => cb(null, `claims/${req.params.claimId}/${file.originalname}`)
  })
});

router.post('/expenses/:claimId/receipts', authenticateEmployee, async (req, res, next) => {
  const claim = await knex('expense_claims')
    .where({ id: req.params.claimId, employee_id: req.user.employeeId })
    .first();
  if (!claim) {
    return res.status(403).json({ error: 'Access denied: expense claim does not belong to you' });
  }
  next();
}, upload.single('receipt'), async (req, res) => {
  const { claimId } = req.params;
  const fileUrl = req.file.location;

  await knex('expense_receipts').insert({
    claim_id: claimId,
    receipt_url: fileUrl,
    uploaded_at: new Date()
  });

  res.status(201).json({ success: true, claimId, fileUrl });
});
